files.contentAfter:
import { db } from './db'
import { escapeHtml } from './html'

export async function search(term: string, sort: string) {
  // Parameterized term is fine; but `sort` is concatenated straight in.
  const sql = `SELECT id, name FROM products WHERE name LIKE $1 ORDER BY ${sort}`
  return db.query(sql, ['%' + term + '%'])
}

export function renderName(name: string): string {
  // Output is HTML-escaped before rendering — safe.
  return `<span>${escapeHtml(name)}</span>`
}
